-- 1943 (2026-11-26): federation game models — 14 national game-model documents (JFA Japan's Way 2025, DBU, KFF, FMF, FRF, SvFF, FAW,
-- TFF, FAT, PSSI Filanesia, RBFA, KFA, Canada, CFA). Same loader as mig 1942. verified = false; official documents noted per model.
-- the duplicate one-off from two sweeps: switch of play = switch play
UPDATE game_common_principle_links l SET principle_id = (SELECT id FROM game_play_principles WHERE code = 'x-switch-play')
 WHERE principle_id = (SELECT id FROM game_play_principles WHERE code = 'x-switch-of-play')
   AND NOT EXISTS (SELECT 1 FROM game_common_principle_links k WHERE k.term_id = l.term_id AND k.principle_id = (SELECT id FROM game_play_principles WHERE code = 'x-switch-play'));
DELETE FROM game_common_principle_links WHERE principle_id = (SELECT id FROM game_play_principles WHERE code = 'x-switch-of-play');
DELETE FROM game_play_principles WHERE code = 'x-switch-of-play';
SELECT 'JFA — Japan''s Way (Play Vision)', 'federation', 'Japan', 50, '2022; 2nd edition Dec 2025',
       (SELECT id FROM game_sources WHERE code = 'jfa'), (SELECT id FROM game_styles WHERE code = NULL),
       (SELECT id FROM game_formation_families WHERE code = NULL), false
ON CONFLICT (name) DO NOTHING;
