SELECT e.id, g.id, 'same' FROM game_source_styles e JOIN game_sources s ON s.id = e.source_id, game_styles g
 WHERE s.code = 'web-frf-ro-wp-content-uploads-2021-06-strategia-tehnica-pdf' AND e.name = 'positional-play' AND e.context = 'FRF — Strategia tehnică: filosofia și stilul de joc' AND g.code = 'positional-play' ON CONFLICT DO NOTHING;
