-- the 🗺 Game models tab's heading for national teams
SELECT 'Football', 'Taxonomy of Football — game models: national teams', 'taxonomy', 'gm_kind_team', NULL, 'National teams', 664, true, true
 WHERE NOT EXISTS (SELECT 1 FROM message_templates m WHERE m.kind = 'taxonomy' AND m.tier = 'gm_kind_team');
