INSERT INTO game_model_moments (model_id, moment, plan, citation) SELECT id, 'in_possession', 'Always attack: scoring is what football is about, so shoot rather than pass and pass forward rather than sideways (without losing the ball); combination play with the third player''s run at high tempo; read the zone and situation — keep it safe or take the bold risk.', 'https://www.jfa.jp/japansway/japansway2026_en.pdf · https://www.jfa.jp/eng/japansway/' FROM game_models WHERE name = 'JFA — Japan''s Way (Play Vision)' ON CONFLICT DO NOTHING;
