INSERT INTO game_model_moments (model_id, moment, plan, citation) SELECT id, 'to_attack', 'Seamless transition to attack: go for goal the moment we regain the ball and attack before their defence is ready; use the wide spaces; otherwise keep secure possession.', 'https://www.jfa.jp/japansway/japansway2026_en.pdf · https://www.jfa.jp/eng/japansway/' FROM game_models WHERE name = 'JFA — Japan''s Way (Play Vision)' ON CONFLICT DO NOTHING;
