INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'to_attack', 2, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'JFA — Japan''s Way (Play Vision)' AND p.code = 'width' ON CONFLICT DO NOTHING;
INSERT INTO game_model_moments (model_id, moment, plan, citation) SELECT id, 'out_of_possession', 'The ball is most important — go and regain it in order to attack: keep pressure on the ball so it is easier to target and win; compactness produces coordinated defence; limit the opponent''s space and time; apply high pressing, win the ball back from a compact defence, protect the goal.', 'https://www.jfa.jp/japansway/japansway2026_en.pdf · https://www.jfa.jp/eng/japansway/' FROM game_models WHERE name = 'JFA — Japan''s Way (Play Vision)' ON CONFLICT DO NOTHING;
