INSERT INTO game_model_moments (model_id, moment, plan, citation) SELECT id, 'to_defend', 'Overwhelmingly fast transitions: switch to regaining the ball the moment it is lost — immediate recovery, stop the ball escaping, control the space behind the line, reorganise the defence.', 'https://www.jfa.jp/japansway/japansway2026_en.pdf · https://www.jfa.jp/eng/japansway/' FROM game_models WHERE name = 'JFA — Japan''s Way (Play Vision)' ON CONFLICT DO NOTHING;
