INSERT INTO game_model_moments (model_id, moment, plan, citation) SELECT id, 'in_possession', 'A ball-possessing style: control every match with the ball — flat build-up from the back line, keep the ball individually and collectively, many layers and lines in the team; play deep before wide (wide passes only prepare a pass in depth); build up on one side, break through on the other.', 'https://www.dbujylland.dk/media/10274/den-roede-traad-m-oevelser.pdf' FROM game_models WHERE name = 'DBU — Den røde tråd (player-development model U15–A national team)' ON CONFLICT DO NOTHING;
INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'in_possession', 3, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'DBU — Den røde tråd (player-development model U15–A national team)' AND p.code = 'keep-ball' ON CONFLICT DO NOTHING;
INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'in_possession', 2, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'DBU — Den røde tråd (player-development model U15–A national team)' AND p.code = 'penetration' ON CONFLICT DO NOTHING;
INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'in_possession', 2, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'DBU — Den røde tråd (player-development model U15–A national team)' AND p.code = 'x-switch-play' ON CONFLICT DO NOTHING;
INSERT INTO game_model_moments (model_id, moment, plan, citation) SELECT id, 'to_defend', 'Counter-press: the nearest players press the ball carrier aggressively the same second the ball is lost, team-mates close their nearest opponent, about five seconds; then organised defence. Be positioned to lose it (a spare defender, back line high); if the counter-press fails, defend the counter from the rest defence, protect space behind and centrally, force the opponent wide.', 'https://www.dbujylland.dk/media/10274/den-roede-traad-m-oevelser.pdf' FROM game_models WHERE name = 'DBU — Den røde tråd (player-development model U15–A national team)' ON CONFLICT DO NOTHING;
INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'to_defend', 3, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'DBU — Den røde tråd (player-development model U15–A national team)' AND p.code = 'immediate-regain' ON CONFLICT DO NOTHING;
INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'to_defend', 2, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'DBU — Den røde tråd (player-development model U15–A national team)' AND p.code = 'x-rest-defence' ON CONFLICT DO NOTHING;
INSERT INTO game_model_moments (model_id, moment, plan, citation) SELECT id, 'out_of_possession', '''We defend the ball instead of the goal'': everyone defends, aggressive, forward and active defending from a compact organisation; press as high as possible at every opportunity, pressure on the ball first, then shut the opponent in and close passing lanes.', 'https://www.dbujylland.dk/media/10274/den-roede-traad-m-oevelser.pdf' FROM game_models WHERE name = 'DBU — Den røde tråd (player-development model U15–A national team)' ON CONFLICT DO NOTHING;
INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'out_of_possession', 3, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'DBU — Den røde tråd (player-development model U15–A national team)' AND p.code = 'pressure' ON CONFLICT DO NOTHING;
INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'out_of_possession', 2, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'DBU — Den røde tråd (player-development model U15–A national team)' AND p.code = 'compactness' ON CONFLICT DO NOTHING;
INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'out_of_possession', 2, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'DBU — Den røde tråd (player-development model U15–A national team)' AND p.code = 'win-back' ON CONFLICT DO NOTHING;
INSERT INTO game_model_moments (model_id, moment, plan, citation) SELECT id, 'to_attack', 'First priority a forward pass to the highest free player, at least two deep runs ahead of the ball and two supporting; keep it central, the carrier draws defenders, team pushes up compact; get into the finishing phase within 5 seconds, else build up. Second priority play away from the opponent''s counter-press and keep the ball.', 'https://www.dbujylland.dk/media/10274/den-roede-traad-m-oevelser.pdf' FROM game_models WHERE name = 'DBU — Den røde tråd (player-development model U15–A national team)' ON CONFLICT DO NOTHING;
INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'to_attack', 3, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'DBU — Den røde tråd (player-development model U15–A national team)' AND p.code = 'x-counter-attack' ON CONFLICT DO NOTHING;
INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'to_attack', 2, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'DBU — Den røde tråd (player-development model U15–A national team)' AND p.code = 'penetration' ON CONFLICT DO NOTHING;
