INSERT INTO game_model_moments (model_id, moment, plan, citation) SELECT id, 'in_possession', 'Pass-oriented play in depth through all playing areas to reach a finish; switches of play and backward depth passes create forward depth while keeping the ball safely; build-up with passing and control, often short passes along the ground; chances from passing plus the attacking weapons challenge, dribble, wall pass and overlap.', 'https://laget.se/TabergsSportklubb/Document/Download/857380/3466429' FROM game_models WHERE name = 'SvFF — Spelarutbildningsplan (spelfilosofi / spelets skeenden)' ON CONFLICT DO NOTHING;
