INSERT INTO game_model_moments (model_id, moment, plan, citation) SELECT id, 'out_of_possession', 'Shrink the opponents'' playing space with ball-oriented defending — zonal marking and/or positional defence — where collective defending methods matter, especially press on the ball carrier; prevent build-up, win the ball back, prevent chances.', 'https://laget.se/TabergsSportklubb/Document/Download/857380/3466429' FROM game_models WHERE name = 'SvFF — Spelarutbildningsplan (spelfilosofi / spelets skeenden)' ON CONFLICT DO NOTHING;
