INSERT INTO game_model_moments (model_id, moment, plan, citation) SELECT id, 'to_attack', 'Fast transitions: on winning the ball counter quickly in depth if the chance is there.', 'https://laget.se/TabergsSportklubb/Document/Download/857380/3466429' FROM game_models WHERE name = 'SvFF — Spelarutbildningsplan (spelfilosofi / spelets skeenden)' ON CONFLICT DO NOTHING;
