INSERT INTO game_model_moments (model_id, moment, plan, citation) SELECT id, 'in_possession', 'Create & exploit overload (''find the spare player''); switch the point of attack based on pressure; break lines — through, around or over depending on the pressure; combine, create and finish in the final third.', 'https://d1zqj8o9na6wgl.cloudfront.net/faw/20230510111722/The-FAW-National-Syllabus.pdf · https://faw.cymru/national-syllabus/' FROM game_models WHERE name = 'FAW — The Welsh Way (National Syllabus game model)' ON CONFLICT DO NOTHING;
