INSERT INTO game_model_moments (model_id, moment, plan, citation) SELECT id, 'out_of_possession', 'Defend the overload by pressuring; prevent and defend the switch; pressure so the opponent cannot play forward between and beyond our lines; minimise threat in our defending third.', 'https://d1zqj8o9na6wgl.cloudfront.net/faw/20230510111722/The-FAW-National-Syllabus.pdf · https://faw.cymru/national-syllabus/' FROM game_models WHERE name = 'FAW — The Welsh Way (National Syllabus game model)' ON CONFLICT DO NOTHING;
