INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'out_of_possession', 2, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'FAW — The Welsh Way (National Syllabus game model)' AND p.code = 'stop-progress' ON CONFLICT DO NOTHING;
