INSERT INTO game_sources (code, kind, title, url, verified) VALUES ('web-kff-kz-en-download-68a465b3b77f6', 'federation', 'Модель игры Казахстанской федерации футбола на 2019 год (KFF)', 'https://kff.kz/en/download/68a465b3b77f6', false) ON CONFLICT (code) DO NOTHING;
INSERT INTO game_model_style_settings (model_id, dimension_id, value) SELECT gm.id, d.id, 2 FROM game_models gm, game_style_dimensions d WHERE gm.name = 'KFF — Game model of the Kazakhstan Football Federation' AND d.code = 'possession' ON CONFLICT DO NOTHING;
INSERT INTO game_model_style_settings (model_id, dimension_id, value) SELECT gm.id, d.id, 2 FROM game_models gm, game_style_dimensions d WHERE gm.name = 'KFF — Game model of the Kazakhstan Football Federation' AND d.code = 'build-up' ON CONFLICT DO NOTHING;
INSERT INTO game_model_moments (model_id, moment, plan, citation) SELECT id, 'in_possession', 'Intelligent, creative, technical team play: constructive build-up from our own goal based on possession, goalkeeper active; reliable short and medium passing for penetrating combinations; patient possession in midfield changing direction and rhythm; lightning-fast actions in the final stage; triangles and numerical superiority everywhere, no duplicated positions.', 'https://kff.kz/en/download/68a465b3b77f6' FROM game_models WHERE name = 'KFF — Game model of the Kazakhstan Football Federation' ON CONFLICT DO NOTHING;
INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'in_possession', 3, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'KFF — Game model of the Kazakhstan Football Federation' AND p.code = 'keep-ball' ON CONFLICT DO NOTHING;
INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'in_possession', 2, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'KFF — Game model of the Kazakhstan Football Federation' AND p.code = 'numerical-superiority' ON CONFLICT DO NOTHING;
INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'in_possession', 2, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'KFF — Game model of the Kazakhstan Football Federation' AND p.code = 'penetration' ON CONFLICT DO NOTHING;
INSERT INTO game_model_moments (model_id, moment, plan, citation) SELECT id, 'out_of_possession', 'Zone-based: near our goal deny entry to the box, compactness and cover; in midfield pressure the ball and stop long balls and crosses; high up control and steer the opponent''s build-up; high press as an option to win it near their goal.', 'https://kff.kz/en/download/68a465b3b77f6' FROM game_models WHERE name = 'KFF — Game model of the Kazakhstan Football Federation' ON CONFLICT DO NOTHING;
INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'out_of_possession', 3, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'KFF — Game model of the Kazakhstan Football Federation' AND p.code = 'pressure' ON CONFLICT DO NOTHING;
INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'out_of_possession', 2, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'KFF — Game model of the Kazakhstan Football Federation' AND p.code = 'compactness' ON CONFLICT DO NOTHING;
INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'out_of_possession', 2, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'KFF — Game model of the Kazakhstan Football Federation' AND p.code = 'cover' ON CONFLICT DO NOTHING;
INSERT INTO game_model_moments (model_id, moment, plan, citation) SELECT id, 'to_defend', 'Either win it back instantly (mostly high up, catching the opponent unbalanced) or retreat to organised defence with the nearest player pressing the carrier so team-mates recover; immediate high press after loss; deny the counter.', 'https://kff.kz/en/download/68a465b3b77f6' FROM game_models WHERE name = 'KFF — Game model of the Kazakhstan Football Federation' ON CONFLICT DO NOTHING;
INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'to_defend', 3, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'KFF — Game model of the Kazakhstan Football Federation' AND p.code = 'immediate-regain' ON CONFLICT DO NOTHING;
INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'to_defend', 2, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'KFF — Game model of the Kazakhstan Football Federation' AND p.code = 'x-recovery-run-recover-shape' ON CONFLICT DO NOTHING;
INSERT INTO game_model_moments (model_id, moment, plan, citation) SELECT id, 'to_attack', 'Either secure the ball (e.g. a back pass) to set up an organised attack, or counter at once: classic (space behind the defence), group (vertical penetrating passes), advanced (regain high), individual break.', 'https://kff.kz/en/download/68a465b3b77f6' FROM game_models WHERE name = 'KFF — Game model of the Kazakhstan Football Federation' ON CONFLICT DO NOTHING;
INSERT INTO game_model_principles (model_id, principle_id, moment, emphasis, own_words) SELECT gm.id, p.id, 'to_attack', 3, '' FROM game_models gm, game_play_principles p WHERE gm.name = 'KFF — Game model of the Kazakhstan Football Federation' AND p.code = 'x-counter-attack' ON CONFLICT DO NOTHING;
