INSERT INTO game_model_moments (model_id, moment, plan, citation) SELECT id, 'out_of_possession', 'Zone-based: near our goal deny entry to the box, compactness and cover; in midfield pressure the ball and stop long balls and crosses; high up control and steer the opponent''s build-up; high press as an option to win it near their goal.', 'https://fmf.md/cdn/docs/proiectul-noi/Концепция игры Национальных сборных Молдовы.pdf' FROM game_models WHERE name = 'FMF Moldova — Game concept of the national teams' ON CONFLICT DO NOTHING;
