INSERT INTO game_model_moments (model_id, moment, plan, citation) SELECT id, 'to_defend', 'Either win it back instantly (mostly high up, catching the opponent unbalanced) or retreat to organised defence with the nearest player pressing the carrier so team-mates recover; immediate high press after loss; deny the counter.', 'https://fmf.md/cdn/docs/proiectul-noi/Концепция игры Национальных сборных Молдовы.pdf' FROM game_models WHERE name = 'FMF Moldova — Game concept of the national teams' ON CONFLICT DO NOTHING;
