INSERT INTO game_model_moments (model_id, moment, plan, citation) SELECT id, 'to_attack', 'Either secure the ball (e.g. a back pass) to set up an organised attack, or counter at once: classic (space behind the defence), group (vertical penetrating passes), advanced (regain high), individual break.', 'https://fmf.md/cdn/docs/proiectul-noi/Концепция игры Национальных сборных Молдовы.pdf' FROM game_models WHERE name = 'FMF Moldova — Game concept of the national teams' ON CONFLICT DO NOTHING;
